#include "../original-tcpe/src/network/java/JavaScoreboardState.h"
#include <cassert>
#include <iostream>
int main(){JavaScoreboardState s;s.objectives["one"].scores["雪"].score=-1;s.objectives["two"].scores["雪"].score=10;s.objectives["two"].scores["Other"].score=20;std::string one="one";s.resetScore("雪",&one);assert(s.objectives["one"].scores.empty()&&s.objectives["two"].scores.count("雪"));s.resetScore("雪",nullptr);assert(!s.objectives["two"].scores.count("雪")&&s.objectives["two"].scores.count("Other"));s.displays[1]="one";s.displays[2]="two";s.removeObjective("one");assert(!s.displays.count(1)&&s.displays[2]=="two");s.teams["a"]=JavaScoreTeam{};s.teams["b"]=JavaScoreTeam{};s.join("a","雪");s.join("a","Other");s.join("b","雪");assert(!s.teams["a"].members.count("雪")&&s.teams["b"].members.count("雪")&&s.memberTeam["雪"]=="b");s.leave("a","雪");assert(s.memberTeam["雪"]=="b");s.join("missing","Ignored");assert(!s.memberTeam.count("Ignored"));s.removeTeam("b");assert(!s.memberTeam.count("雪")&&s.memberTeam["Other"]=="a");s.objectives["main"].number.kind="blank";for(int i=0;i<16;++i)s.objectives["main"].scores[std::to_string(i)].score=i;s.objectives["main"].scores["#hidden"].score=999;auto rows=s.rows(s.objectives["main"]);assert(rows.size()==15&&rows.front().score==15&&rows.back().score==1&&rows.front().number.empty());s.displays[1]="main";s.teams["a"].color=11;s.displays[14]="alternate";s.objectives["alternate"].text="Team board";assert(s.sidebar("Other")->text=="Team board");s.displays.erase(14);assert(s.sidebar("Other")==&s.objectives["main"]);s.objectives["tie"].scores["Zulu"].score=3;s.objectives["tie"].scores["alpha"].score=3;auto tied=s.rows(s.objectives["tie"]);assert(tied[0].owner=="alpha");s.objectives["tie"].scores["alpha"].hasDisplay=true;s.objectives["tie"].scores["alpha"].display="雪";s.objectives["tie"].scores["alpha"].number.kind="fixed";s.objectives["tie"].scores["alpha"].number.text="✦";tied=s.rows(s.objectives["tie"]);assert(tied[0].label=="雪"&&tied[0].number=="✦");s.objectives["styled"].number.kind="styled";s.objectives["styled"].number.text="§x§1§2§3§4§5§0§l";s.objectives["styled"].scores["negative"].score=-42;assert(s.rows(s.objectives["styled"])[0].number=="§x§1§2§3§4§5§0§l-42");s.clear();assert(s.objectives.empty()&&s.displays.empty()&&s.teams.empty()&&s.memberTeam.empty());std::cout<<"Scoreboard state: scoped/all resets, objective-display cleanup, team movement and owner consistency, clear PASS\n";}
